namespace Nte.Login;

// Context IDs are generated by the owned bridge, not account identifiers.
internal readonly record struct NteGlobalSdkQuery(uint Notification, int ContextId)
{
    internal uint ReplyCommand => Notification switch
    {
        104 => 1540, // global_GetIpLocationJson: its dedicated callback map.
        113 => 1531, // global_getPlatformWithContextId: the common callback map.
        _ => throw new InvalidOperationException("Unsupported global SDK query.")
    };
    internal string ServicePath => Notification switch
    {
        104 => "/c/api/ip/getData",
        113 => "/c/api/ip/platform",
        _ => throw new InvalidOperationException("Unsupported global SDK query.")
    };
    internal static bool TryCreate(uint notification, nint parameter, out NteGlobalSdkQuery request)
    {
        request = default;
        if (notification is not (104 or 113) || parameter < 0 || (long)parameter > int.MaxValue) return false;
        request = new(notification, (int)parameter); return true;
    }
}
